@namespace sv_6a4b6032b71c464a92ee4bddc5c68829.Components.Pages.Apply

<div class="references-step">
    <h3>References</h3>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@References[index]"
                       Index="index"
                       ShowRemove="@(References.Count > 1)"
                       OnChanged="e => HandleReferenceChanged(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(validationMessage))
    {
        <div class="validation-error">@validationMessage</div>
    }

    <div class="step-buttons">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceForm.ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    private void HandleReferenceChanged(int index, ReferenceForm.ReferenceModel updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceForm.ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationMessage = null;

        if (References.Count < 2)
        {
            validationMessage = "Please provide at least 2 references.";
            return;
        }

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationMessage = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }
}

