+@namespace sv_6a4b6032b71c464a92ee4bddc5c68829.Components.Pages.Apply
+
+<nav class="step-indicator">
+    @for (int i = 0; i < StepNames.Count; i++)
+    {
+        var stepIndex = i;
+        var status = GetStepStatus(stepIndex);
+        <button class="step @status"
+                disabled="@(status == "future")"
+                @onclick="() => OnStepClick(stepIndex)">
+            <span class="step-number">
+                @if (status == "completed")
+                {
+                    <span class="checkmark">&#10003;</span>
+                }
+                else
+                {
+                    @(stepIndex + 1)
+                }
+            </span>
+            <span class="step-name">@StepNames[stepIndex]</span>
+        </button>
+    }
+</nav>
+
+@code {
+    [Parameter] public int CurrentStep { get; set; }
+    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
+    [Parameter] public EventCallback<int> OnStepSelected { get; set; }
+
+    private static readonly List<string> StepNames = new()
+    {
+        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
+    };
+
+    private string GetStepStatus(int index)
+    {
+        if (index == CurrentStep) return "current";
+        if (CompletedSteps.Contains(index)) return "completed";
+        return "future";
+    }
+
+    private async Task OnStepClick(int index)
+    {
+        if (CompletedSteps.Contains(index))
+        {
+            await OnStepSelected.InvokeAsync(index);
+        }
+    }
+}
