toolArgs.file_text:
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    justify-content: space-between;
    margin-bottom: 2rem;
    padding: 0;
    border-bottom: 2px solid #e0e0e0;
    padding-bottom: 1rem;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    opacity: 1;
    transition: opacity 0.2s;
}

.step-indicator .step.future {
    opacity: 0.4;
    cursor: not-allowed;
}

.step-indicator .step.current .step-number {
    background-color: #0d6efd;
    color: white;
}

.step-indicator .step.completed .step-number {
    background-color: #198754;
    color: white;
}

.step-number {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #e0e0e0;
    font-weight: bold;
    font-size: 0.875rem;
}

.step-name {
    font-size: 0.75rem;
    text-align: center;
    max-width: 80px;
}

.checkmark {
    font-weight: bold;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

.btn-next, .btn-submit {
    padding: 0.625rem 1.5rem;
    background-color: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}

.btn-next:hover, .btn-submit:hover {
    background-color: #0b5ed7;
}

.btn-back {
    padding: 0.625rem 1.5rem;
    background-color: #6c757d;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}

.btn-back:hover {
    background-color: #5c636a;
}

.btn-add {
    padding: 0.5rem 1rem;
    background-color: #198754;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-add:hover {
    background-color: #157347;
}

.btn-remove {
    padding: 0.25rem 0.75rem;
    background-color: #dc3545;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.875rem;
}

.btn-remove:hover {
    background-color: #bb2d3b;
}

.btn-edit {
    padding: 0.25rem 0.75rem;
    background: none;
    border: 1px solid #0d6efd;
    color: #0d6efd;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.875rem;
}

.btn-edit:hover {
    background-color: #0d6efd;
    color: white;
}

button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

/* Validation */
.validation-error {
    color: #dc3545;
    margin-top: 0.5rem;
    padding: 0.5rem;
    background-color: #f8d7da;
    border-radius: 4px;
}

.field-error {
    color: #dc3545;
    font-size: 0.875rem;
}

/* Work Entry & Reference Forms */
.work-entry-form, .reference-form {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4 {
    margin: 0;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px !important;
}

.char-count {
    text-align: right;
    font-size: 0.875rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

/* Review Step */
.review-section {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.section-header h4 {
    margin: 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.5rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #6c757d;
}

.work-review-entry, .reference-review-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.work-review-entry:last-child, .reference-review-entry:last-child {
    border-bottom: none;
}

.date-range {
    font-size: 0.875rem;
    color: #6c757d;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background-color: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem;
    background-color: #d1e7dd;
    border-radius: 8px;
}

.confirmation h4 {
    color: #198754;
    font-size: 1.5rem;
}

.step-description {
    color: #6c757d;
    margin-bottom: 1rem;
}

