@namespace sv_6a4b6032b71c464a92ee4bddc5c68829.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd"))"
                   disabled="@Entry.IsCurrent"
                   @onchange="OnEndDateChanged" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@Entry.IsCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="OnDescriptionChanged"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void OnCompanyChanged(ChangeEventArgs e)
    {
        Entry.Company = e.Value?.ToString() ?? "";
        OnChanged.InvokeAsync(Entry);
    }

    private void OnTitleChanged(ChangeEventArgs e)
    {
        Entry.Title = e.Value?.ToString() ?? "";
        OnChanged.InvokeAsync(Entry);
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var d))
            Entry.StartDate = d;
        OnChanged.InvokeAsync(Entry);
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        Entry.EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null;
        OnChanged.InvokeAsync(Entry);
    }

    private void OnDescriptionChanged(ChangeEventArgs e)
    {
        Entry.Description = e.Value?.ToString() ?? "";
        OnChanged.InvokeAsync(Entry);
    }

    private void HandleCurrentToggle(ChangeEventArgs e)
    {
        var isChecked = (bool)(e.Value ?? false);
        Entry.IsCurrent = isChecked;
        if (isChecked) Entry.EndDate = null;
        OnChanged.InvokeAsync(Entry);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

